    std::uint64_t aCross = 0; std::uint64_t aScatter = 0;

    std::uint64_t aOrbiterA = 0; std::uint64_t aOrbiterB = 0; std::uint64_t aOrbiterC = 0; std::uint64_t aOrbiterD = 0;
    std::uint64_t aOrbiterE = 0; std::uint64_t aOrbiterF = 0; std::uint64_t aOrbiterG = 0; std::uint64_t aOrbiterH = 0;
    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [seed arx]
    std::uint8_t *aSource = pWorkSpace->mSource;
    READ_IN_MUTABLE_PARAMS;
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseB(pNonce * 0xA927AC1DBC4B6ADFULL + 0xBF3328FF9B6DD037ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordB = TwistMix64::DiffuseB(pNonce * 0x8ED99B3246CBEA13ULL + 0xD0E2CE1B8BFF8B27ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordC = TwistMix64::DiffuseA(pNonce * 0xA78FDEB148C1C2ADULL + 0x97DB7C466AA88C86ULL);
