            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererE = aWandererE ^ (((RotL64(aPrevious, 3U) + aOrbiterE) + RotL64(aOrbiterA, 39U)) + aTwistWandererUpdateSaltC[(((31U - aIndex) + 21U)) & S_SALT1]);
