            aOrbiterA = (aWandererC + RotL64(aCross, 14U)) + 0x72E6CDC9C0D75278ULL;
            aOrbiterC = ((aWandererE + RotL64(aIngress, 39U)) + RotL64(aCarry, 5U)) + 0x6D48BB0E9E9D144AULL;
            aOrbiterE = (aWandererJ + RotL64(aScatter, 53U)) + 0xA477F5CB1F079F11ULL;
            aOrbiterG = ((aWandererI + RotL64(aIngress, 3U)) + 0x3F48A2B91C964943ULL) + aTwistOrbiterAssignSaltD[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterJ = ((aWandererF + RotL64(aCross, 42U)) + RotL64(aCarry, 27U)) + 0x16F3AA6073273379ULL;
