            aOrbiterF = (aWandererB + RotL64(aScatter, 51U)) + 0x67EB8DA9D029A209ULL;
            aOrbiterB = ((aWandererH + RotL64(aCross, 11U)) + 0xC90133D3A431852DULL) + aTwistOrbiterAssignSaltF[((aIndex + 19U)) & S_SALT1];
            aOrbiterK = (aWandererG + RotL64(aPrevious, 35U)) + 0x68178AF23525EDD0ULL;
            aOrbiterH = ((aWandererD + RotL64(aScatter, 19U)) + RotL64(aCarry, 37U)) + 0xA90FA2D686EF3B40ULL;
            //
            aOrbiterD = ((aOrbiterD + aOrbiterA) + 0xB62236CECA9B9C23ULL) + aTwistOrbiterUpdateSaltA[((aIndex + 15U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterD) ^ 0x907279DB48BE0713ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xCE0D4E1F4DC32243ULL), 11U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterG) + 0x6A07C2398839322DULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterE) ^ 0xB5B6FDF0B9051A9CULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x06A53845566259FBULL), 57U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterI) + 0xCA34BE5A1A9616DDULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterA) ^ 0x3BDF8645E7B309D5ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x2A9C9265E8D93717ULL), 47U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterE) + 0x7E168EA75E7317C8ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterB) ^ 0xF756161ACC1F47C2ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xD8D91D3036E6CCF9ULL), 51U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterF) + 0x4E56E8BB5EDC05E8ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterC) ^ 0x91322FCA648E5C66ULL) ^ aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x27C62C974DB1D0F1ULL), 29U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterD) + 0x2F850537ADFA7D99ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterJ) ^ 0x950C9B78DCE7315BULL;
            aOrbiterI = RotL64((aOrbiterI * 0xA1786DF2B1E499ADULL), 43U);
