            aOrbiterB = ((aWandererF + RotL64(aPrevious, 11U)) + 0x317B4C8E823DAD6FULL) + aTwistOrbiterAssignSaltF[((aIndex + 11U)) & S_SALT1];
            aOrbiterA = (((aWandererG + RotL64(aIngress, 60U)) + RotL64(aCarry, 43U)) + 0x1EBCA9C3F6952CABULL) + aTwistOrbiterAssignSaltC[((aIndex + 29U)) & S_SALT1];
            aOrbiterE = (aWandererD + RotL64(aCross, 3U)) + 0xD1E6553CB1B6AA2DULL;
