            //
            aOrbiterE = ((aOrbiterE + aOrbiterB) + 0x243674A3B7C4A531ULL) + aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 26U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterE) ^ 0xCB79AE8E1DD4A2E7ULL;
