            //
            aOrbiterK = ((aOrbiterK + aOrbiterF) + 0xCAC89F2F33F27DA2ULL) + aTwistOrbiterUpdateSaltC[((aIndex + 6U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterK) ^ 0x3A9305959DD88DD2ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x5EF84F737A7A568BULL), 57U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterC) + 0x0ED66CDE2D4EB557ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterF) ^ 0xAB6262F49BD0A566ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x62FC55FA139F3B25ULL), 13U);
