            aScatter = TwistMix64::DiffuseA((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterI = (aWandererG + RotL64(aPrevious, 5U)) + 0x9DB0C1A8AE2ED661ULL;
            aOrbiterJ = (((aWandererA + RotL64(aIngress, 21U)) + RotL64(aCarry, 23U)) + 0xD2D7A3D9DCCE6692ULL) + aTwistOrbiterAssignSaltB[(((31U - aIndex) + 13U)) & S_SALT1];
