            aOrbiterE = (((aWandererK + RotL64(aScatter, 41U)) + RotL64(aCarry, 57U)) + 0xDF868766AFBA081DULL) + aTwistOrbiterAssignSaltD[((aIndex + 26U)) & S_SALT1];
            aOrbiterG = ((aWandererD + RotL64(aPrevious, 57U)) + RotL64(aCarry, 37U)) + 0x9C43CB43C06A1387ULL;
            //
            aOrbiterI = (aOrbiterI + aOrbiterJ) + 0x66ACB4C75691E2D9ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterI) ^ 0x61C135AE388C908EULL;
            aOrbiterH = RotL64((aOrbiterH * 0x6BD0BA81C289BA59ULL), 21U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0xB8CE2A8FA29860FBULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterB) ^ 0x83688657E32BF69AULL;
            aOrbiterI = RotL64((aOrbiterI * 0x2F1D35D17B982AF1ULL), 3U);
