            aOrbiterE = (aOrbiterE + aOrbiterH) + 0x1274251C625ED8CFULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterE) ^ 0x84D2AA791379ACBCULL) ^ aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x3E694D424D350D55ULL), 29U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterG) + 0x999E9A0D7AD84867ULL) + aTwistOrbiterUpdateSaltB[((aIndex + 29U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterC) ^ 0x815DF20CA582882DULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x34AE1ADE70A334ABULL), 35U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterI) + 0x0C87A4BDE1B3CABAULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterG) ^ 0xB2B66659248535DEULL;
            aOrbiterE = RotL64((aOrbiterE * 0xB2E5DCB6879DB293ULL), 57U);
