            aOrbiterH = (aOrbiterH + aOrbiterB) + 0x5A0E9EEB257ACF1DULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterH) ^ 0xC7D8E0AF880EAC17ULL) ^ aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 28U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x3B03DB44BABA38E5ULL), 41U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterE) + 0x661E9D08472DBD92ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterJ) ^ 0x193E9746383A5B47ULL) ^ aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x17CDD3E572452B57ULL), 47U);
            //
            aIngress = RotL64(aOrbiterI, 57U) ^ aOrbiterB;
