            //
            aScatter = (RotL64(aPrevious, 24U) + RotL64(aCarry, 53U)) + (RotL64(aIngress, 37U) ^ RotL64(aCross, 3U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterJ = ((aWandererC + RotL64(aIngress, 37U)) + RotL64(aCarry, 13U)) + 0x9C4DBD7076901AF9ULL;
            aOrbiterG = ((aWandererF + RotL64(aScatter, 11U)) + 0x41416C6167C8EF43ULL) + aTwistOrbiterAssignSaltA[(((31U - aIndex) + 26U)) & S_SALT1];
            aOrbiterK = ((aWandererI + RotL64(aCross, 43U)) + RotL64(aCarry, 41U)) + 0xB5573D0338AA0E4FULL;
