            //
            aOrbiterD = ((aWandererH + RotL64(aIngress, 58U)) + 0xCA9A4A70BC184A70ULL) + aKeyRotateAOrbiterAssignSaltC[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterI = (aWandererG + RotL64(aScatter, 5U)) + 0x7A339903733AF98AULL;
            aOrbiterK = (aWandererC + RotL64(aCross, 19U)) + 0xE29750E3EDF6ECC6ULL;
            aOrbiterB = (aWandererB + RotL64(aPrevious, 23U)) + 0x9D419D571710FB28ULL;
            aOrbiterE = (aWandererF + RotL64(aIngress, 29U)) + 0x0DE28FD1A26CE498ULL;
            aOrbiterG = (aWandererJ + RotL64(aScatter, 53U)) + 0xEC218CD2AA87429BULL;
            aOrbiterC = (((aWandererI + RotL64(aPrevious, 47U)) + RotL64(aCarry, 37U)) + 0xD4CA498854303378ULL) + aKeyRotateAOrbiterAssignSaltF[((aIndex + 6U)) & S_SALT1];
            aOrbiterJ = ((aWandererA + RotL64(aCross, 13U)) + RotL64(aCarry, 29U)) + 0xA514AB56B259BA8EULL;
            aOrbiterH = ((aWandererK + RotL64(aScatter, 42U)) + RotL64(aCarry, 21U)) + 0xAC550C9177D29A33ULL;
            //
            aOrbiterD = (aOrbiterD + aOrbiterI) + 0xA812594147D80D2CULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterD) ^ 0x3847DEF3E2D50818ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x36CFE4A810749825ULL), 53U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterE) + 0x315DC711B9418CA2ULL) + aKeyRotateAOrbiterUpdateSaltC[(((31U - aIndex) + 21U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterB) ^ 0xB4616B48C221D0CBULL;
            aOrbiterG = RotL64((aOrbiterG * 0x4B4AA2EFDF89D6AFULL), 11U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterB) + 0xC1A0755AA64FBC3AULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterK) ^ 0x83C9D1F5A637B1CDULL;
            aOrbiterC = RotL64((aOrbiterC * 0xBB77F6376B71CCC5ULL), 57U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterJ) + 0xB16D8816458F89E7ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterI) ^ 0x7DE0D3DF9C587854ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x82FE3C7DB19DAB9FULL), 29U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterG) + 0x29EEDA143C44BC70ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterC) ^ 0xCC4E0A1E3E316CC1ULL) ^ aKeyRotateAOrbiterUpdateSaltB[((aIndex + 11U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x7F236E82A6FB0A0DULL), 35U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterD) + 0x9428AD4326520B01ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterJ) ^ 0x13825EE77CF828FEULL;
            aOrbiterE = RotL64((aOrbiterE * 0x1FCA89FA488C8C89ULL), 19U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterC) + 0x389BC2C1933CA911ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterH) ^ 0x2B11925813D84661ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xCFA92D7D0B3A1A23ULL), 23U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterH) + 0xA81527CC7264A81EULL;
