            //
            aOrbiterE = ((aOrbiterE + aOrbiterK) + 0x82DCE3DE624D1FDAULL) + aKeyRotateAOrbiterUpdateSaltF[((aIndex + 12U)) & S_SALT1];
            aOrbiterH = ((aOrbiterH ^ aOrbiterE) ^ 0x78E352D0D297DE4BULL) ^ aKeyRotateAOrbiterUpdateSaltE[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x36CA938261743AF1ULL), 39U);
            //
            aIngress = RotL64(aOrbiterH, 37U) ^ aOrbiterB;
