            aIngress ^= (RotL64(aShadowLaneB[((aIndex + 3628U)) & S_BLOCK1], 58U) ^ RotL64(aWaterLaneA[((aIndex + 1726U)) & S_BLOCK1], 5U));
            aIngress = TwistMix64::DiffuseB((aIngress ^ aKeyRotateADomainWordIngress));
