            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aCross, 13U) ^ RotL64(aIngress, 56U)) + (RotL64(aPrevious, 27U) + RotL64(aCarry, 43U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterK = (aWandererJ + RotL64(aPrevious, 39U)) + 0x5517B50ED0D74620ULL;
            aOrbiterA = ((aWandererF + RotL64(aCross, 19U)) + RotL64(aCarry, 19U)) + 0x15DD66817C4D4EA3ULL;
            aOrbiterD = ((aWandererA + RotL64(aScatter, 29U)) + 0x761D124BFAC188A3ULL) + aKeyRotateAOrbiterAssignSaltB[((aIndex + 27U)) & S_SALT1];
            aOrbiterB = (aWandererC + RotL64(aIngress, 11U)) + 0xFB93E336AE12FA66ULL;
            aOrbiterH = ((aWandererK + RotL64(aPrevious, 5U)) + RotL64(aCarry, 35U)) + 0x1A6D4312484A2F64ULL;
            aOrbiterE = (aWandererG + RotL64(aIngress, 56U)) + 0xED7D67BB437BC8AEULL;
            aOrbiterF = (((aWandererI + RotL64(aScatter, 47U)) + RotL64(aCarry, 57U)) + 0x6691E034545D03C0ULL) + aKeyRotateAOrbiterAssignSaltE[(((31U - aIndex) + 12U)) & S_SALT1];
            //
            aOrbiterK = (aOrbiterK + aOrbiterA) + 0x611511494FD87EC8ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterK) ^ 0x87B712275F81BC26ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x05578208BAB6D453ULL), 35U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterD) + 0xCB884D8E83CCA35BULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0x140B99AB373AB227ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xAD35DEAF4A177905ULL), 27U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterE) + 0x536F69B129085EA6ULL) + aKeyRotateAOrbiterUpdateSaltD[(((31U - aIndex) + 19U)) & S_SALT1];
            aOrbiterF = ((aOrbiterF ^ aOrbiterD) ^ 0x25DB0F78B5814D4BULL) ^ aKeyRotateAOrbiterUpdateSaltE[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x3DE667A68E0DB7F5ULL), 41U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterB) + 0xA747187E551140B0ULL) + aKeyRotateAOrbiterUpdateSaltF[((aIndex + 20U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterF) ^ 0x0753732E788AD61DULL;
            aOrbiterA = RotL64((aOrbiterA * 0x8C2FB0854EFE5FD7ULL), 13U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterF) + 0x9E25384731A9ADC9ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterH) ^ 0x9A7F11A1C5352ABEULL) ^ aKeyRotateAOrbiterUpdateSaltA[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0xD1D88CEEF331BDC3ULL), 3U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterH) + 0x433BDD54A1209C63ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterA) ^ 0x814096539F0B633DULL;
            aOrbiterE = RotL64((aOrbiterE * 0x37A3E5A188AFBC97ULL), 19U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterK) + 0x35617B38B6D5ACFCULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterE) ^ 0xAB1A376679EF9ED5ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xD1595B788A2C4E65ULL), 53U);
            //
            aIngress = aOrbiterK ^ RotL64(aOrbiterH, 53U);
            aIngress = aIngress + (aOrbiterD ^ RotL64(aOrbiterF, 19U));
            aIngress = aIngress + (RotL64(aOrbiterA, 44U) ^ aOrbiterB);
            aIngress = aIngress + RotL64(aOrbiterE, 27U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererA = aWandererA ^ ((RotL64(aIngress, 51U) + aOrbiterF) + RotL64(aOrbiterB, 50U));
            aWandererI = aWandererI + (((RotL64(aScatter, 19U) + aOrbiterB) + RotL64(aOrbiterH, 19U)) + RotL64(aCarry, 29U));
            aWandererG = aWandererG ^ (((RotL64(aPrevious, 44U) + aOrbiterE) + RotL64(aOrbiterA, 27U)) + aKeyRotateAWandererUpdateSaltB[(((31U - aIndex) + 9U)) & S_SALT1]);
            aWandererJ = aWandererJ + ((((RotL64(aCross, 11U) + RotL64(aOrbiterH, 57U)) + aOrbiterF) + RotL64(aCarry, 5U)) + aKeyRotateAWandererUpdateSaltC[((aIndex + 25U)) & S_SALT1]);
            aWandererF = aWandererF ^ ((RotL64(aPrevious, 27U) + RotL64(aOrbiterK, 41U)) + aOrbiterD);
