            //
            aIngress = (RotL64(aFuseLaneA[((aIndex + 14707U)) & S_BLOCK1], 3U) ^ RotL64(aWindLaneC[((aIndex + 12573U)) & S_BLOCK1], 57U));
            aIngress ^= (RotL64(aMagmaLaneB[((aIndex + 15403U)) & S_BLOCK1], 28U) ^ RotL64(aKeyRowReadB[(((2047U - aIndex) + 9573U)) & W_KEY1], 37U));
            aIngress = TwistMix64::DiffuseC((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aWindLaneA[((S_BLOCK1 - aIndex + 13953U)) & S_BLOCK1], 53U) ^ RotL64(aWindLaneD[((S_BLOCK1 - aIndex + 15617U)) & S_BLOCK1], 6U));
            aCross ^= (RotL64(aWoodLaneA[((S_BLOCK1 - aIndex + 12144U)) & S_BLOCK1], 21U) ^ RotL64(aSoilLaneA[((aIndex + 9413U)) & S_BLOCK1], 35U));
            aCross = TwistMix64::DiffuseA((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 51U) + RotL64(aCarry, 5U)) ^ (RotL64(aIngress, 22U) ^ RotL64(aCross, 35U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterC = ((aWandererB + RotL64(aPrevious, 43U)) + RotL64(aCarry, 35U)) + 0x7D3C2E6CC12642E1ULL;
            aOrbiterJ = ((aWandererK + RotL64(aScatter, 27U)) + RotL64(aCarry, 5U)) + 0x5B4527BDEF023963ULL;
            aOrbiterK = (aWandererD + RotL64(aCross, 52U)) + 0xCE363A4C8117639BULL;
            aOrbiterB = ((aWandererC + RotL64(aIngress, 19U)) + RotL64(aCarry, 53U)) + 0xE1564A5BE328740DULL;
            aOrbiterH = ((aWandererA + RotL64(aScatter, 13U)) + 0x4E2AA2BB54125A0AULL) + aKeyRotateAOrbiterAssignSaltA[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterF = ((aWandererI + RotL64(aCross, 3U)) + 0x8B34FB14DE5AB01CULL) + aKeyRotateAOrbiterAssignSaltD[(((31U - aIndex) + 28U)) & S_SALT1];
            aOrbiterD = (aWandererH + RotL64(aPrevious, 35U)) + 0xFCE2931858BC7898ULL;
            //
            aOrbiterC = ((aOrbiterC + aOrbiterJ) + 0xDC1776E249BB150DULL) + aKeyRotateAOrbiterUpdateSaltD[(((31U - aIndex) + 17U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterC) ^ 0x29D6E67573A1B783ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x5C8679A6A6375767ULL), 53U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterH) + 0xAF93460E85CE4745ULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterB) ^ 0x43C9194789D4394EULL) ^ aKeyRotateAOrbiterUpdateSaltC[(((31U - aIndex) + 10U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0xB9A880E0F8C982AFULL), 35U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterF) + 0x4D8652ACD77C39A6ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterJ) ^ 0x9467AAA0B441C576ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x8FEF9CB50E2BA9D7ULL), 13U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterK) + 0x25962D75D3D9324DULL) + aKeyRotateAOrbiterUpdateSaltA[((aIndex + 15U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterF) ^ 0x058A3C37086426E5ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x27045653DA0D5E1DULL), 3U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterB) + 0xE44D9B958DBBD3A8ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterK) ^ 0xCBDA704B40D9473BULL) ^ aKeyRotateAOrbiterUpdateSaltB[(((31U - aIndex) + 26U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0xAE8A997D243644A7ULL), 43U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterC) + 0x30BAA9E221E9F1AAULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterD) ^ 0xD4BDB115ECB85494ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xC2AB0340F9A5D20FULL), 29U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterD) + 0x75C5F5159ACAC111ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterH) ^ 0x7DE05CB39A3E90BBULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x952F4ED90FEB5535ULL), 21U);
            //
            aIngress = RotL64(aOrbiterB, 60U) ^ aOrbiterC;
            aIngress = aIngress + (RotL64(aOrbiterH, 27U) ^ aOrbiterJ);
            aIngress = aIngress + (aOrbiterF ^ RotL64(aOrbiterK, 13U));
            aIngress = aIngress + RotL64(aOrbiterD, 47U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererK = aWandererK + (((RotL64(aPrevious, 35U) + RotL64(aOrbiterD, 3U)) + aOrbiterH) + aKeyRotateAWandererUpdateSaltA[((aIndex + 18U)) & S_SALT1]);
