            aOrbiterK = (aWandererI + RotL64(aCross, 47U)) + 0x8850DFB9C9691C1BULL;
            aOrbiterB = ((aWandererG + RotL64(aScatter, 34U)) + RotL64(aCarry, 23U)) + 0xDD24D10F83F7334AULL;
