            aOrbiterK = ((aOrbiterK ^ aOrbiterF) ^ 0x2C08FC664D40B2ACULL) ^ aKeyRotateBOrbiterUpdateSaltE[(((31U - aIndex) + 6U)) & S_SALT1];
